// ratelimit.go
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// SystemClock is the production Clock.
type SystemClock struct{}

// Now returns the current wall-clock time.
func (SystemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Buckets start full. Tokens refill continuously at rate r.
type Limiter struct {
	mu        sync.Mutex
	clock     Clock
	capacity  int
	tokens    float64
	refillPer float64 // tokens per second
	last      time.Time
}

// NewLimiter creates a Limiter with the given burst capacity and refill rate
// (tokens per second). Both must be positive.
func NewLimiter(capacity int, refillPerSec float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("capacity must be positive, got %d", capacity)
	}
	if refillPerSec <= 0 {
		return nil, fmt.Errorf("refillPerSec must be positive, got %v", refillPerSec)
	}
	if clock == nil {
		return nil, errors.New("clock must not be nil")
	}
	return &Limiter{
		clock:     clock,
		capacity:  capacity,
		tokens:    float64(capacity),
		refillPer: refillPerSec,
		last:      clock.Now(),
	}, nil
}

// AllowN reports whether n tokens may be consumed at this instant,
// consuming them if so.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(float64(l.capacity), l.tokens+elapsed*l.refillPer)
		l.last = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether a single token may be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	if elapsed > 0 {
		return min(float64(l.capacity), l.tokens+elapsed*l.refillPer)
	}
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
