// ratelimit_test.go
package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock(start time.Time) *fakeClock { return &fakeClock{t: start} }

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewLimiterValidation(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	cases := []struct {
		name    string
		cap     int
		rate    float64
		clock   Clock
		wantErr bool
	}{
		{"ok", 1, 1, clock, false},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 1, 0, clock, true},
		{"negative rate", 1, -0.5, clock, true},
		{"nil clock", 1, 1, nil, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := NewLimiter(tc.cap, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("NewLimiter() error = %v, wantErr %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	cases := []struct {
		name     string
		cap      int
		rate     float64
		steps    []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name: "burst up to capacity then denied",
			cap:  3, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true}, {0, 1, true}, {0, 1, true}, {0, 1, false},
			},
		},
		{
			name: "refill over time",
			cap:  2, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true}, {0, 1, false},
				{time.Second, 1, true}, {0, 1, false},
				{2 * time.Second, 2, true},
			},
		},
		{
			name: "refill capped at capacity",
			cap:  1, rate: 10,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true}, {time.Hour, 1, true}, {0, 1, false},
			},
		},
		{
			name: "zero request always allowed",
			cap:  1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true}, {0, 0, true}, {0, 0, true},
			},
		},
		{
			name: "negative request denied",
			cap:  1, rate: 1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false}, {0, 1, true},
			},
		},
		{
			name: "fractional refill accumulates",
			cap:  1, rate: 2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true}, {0, 1, false},
				{250 * time.Millisecond, 1, false},
				{250 * time.Millisecond, 1, true},
			},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock(base)
			l, err := NewLimiter(tc.cap, tc.rate, clock)
			if err != nil {
				t.Fatalf("NewLimiter: %v", err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := l.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestTokensRefillsContinuously(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, _ := NewLimiter(2, 1, clock)
	l.AllowN(2)
	if got := l.Tokens(); got != 0 {
		t.Fatalf("Tokens() = %v, want 0", got)
	}
	clock.Advance(500 * time.Millisecond)
	if got := l.Tokens(); got != 0.5 {
		t.Fatalf("Tokens() = %v, want 0.5", got)
	}
}

func TestConcurrentUse(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, _ := NewLimiter(100, 100, clock)
	var wg sync.WaitGroup
	allowed := make([]bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			allowed[i] = l.Allow()
		}(i)
	}
	wg.Wait()
	count := 0
	for _, ok := range allowed {
		if ok {
			count++
		}
	}
	if count != 100 {
		t.Fatalf("allowed %d requests, want 100", count)
	}
}
